#!/usr/bin/env python3
"""
Fórmula do Gol — correção completa: e-mail do Worker por SMTP + reparo dos zips.

Rode na RAIZ do repositório, no Codespaces:
    git pull
    python3 corrigir_fdg_email.py            # aplica
    python3 corrigir_fdg_email.py --dry-run  # só mostra o que faria

O que faz, nesta ordem:
  1. Recupera, pelo histórico do git, o que os zips anteriores sobrescreveram
     (workflow de deploy, package.json, wrangler.template.jsonc e os arquivos
     do fastlane) e reaplica só as mudanças do fastlane por cima.
  2. Liga o e-mail do Worker ao SMTP que já existe (SMTP_HOST/PORT/USER/PASS
     + EMAIL_DESTINO_SUGESTOES): alerta de público não localizado e alerta de
     jogo que não está READY.
  3. Faz o smoke test do deploy ler a versão do fastlane a partir do código.
  4. Valida tudo (sintaxe, testes, YAML). Se qualquer validação falhar,
     desfaz todas as alterações e não deixa nada pela metade.
Não faz commit: ao final mostra os comandos.
"""
from __future__ import annotations

import base64, gzip, json, os, re, subprocess, sys, tempfile
from pathlib import Path

DATA = {
"base_fast": "",
"base_fast_test": "",
"base_importer": "",
"v3_fast": "",
"v3_fast_test": "",
"v3_importer": "",
"v3_template": "",
"v3_pkg": "",
"fix5_workflow": "",
"novo_fast": "",
"mailer": "",
"mailer_test": "",
"migration": "",
"readiness_old": "",
"readiness_new": ""
}

W = "cloudflare/push-worker"
P_FAST = f"{W}/src/postgame-fastlane.js"
P_FAST_TEST = f"{W}/tests/test-postgame-fastlane.mjs"
P_MAILER = f"{W}/src/mailer.js"
P_MAILER_TEST = f"{W}/tests/test-mailer.mjs"
P_MIGR = f"{W}/migrations/0010_postgame_public_ai.sql"
P_TEMPLATE = f"{W}/wrangler.template.jsonc"
P_PKG = f"{W}/package.json"
P_MONITOR = f"{W}/src/sports-monitor.js"
P_IMPORTER = "scripts/completar_publicos_ia.py"
P_WORKFLOW = ".github/workflows/deploy-push-worker.yml"

DRY = "--dry-run" in sys.argv
avisos: list[str] = []
erros: list[str] = []
relatorio: list[str] = []


def blob(nome: str) -> bytes:
    return gzip.decompress(base64.b64decode(DATA[nome]))


def git(*args: str, check: bool = True) -> subprocess.CompletedProcess:
    return subprocess.run(["git", *args], capture_output=True, check=check)


def ler(path: str) -> bytes | None:
    p = Path(path)
    return p.read_bytes() if p.exists() else None


def versao_antes_do_meu_zip(path: str, entregue: bytes) -> tuple[str | None, bytes | None]:
    """Acha o commit que gravou exatamente o arquivo que eu entreguei e devolve
    o conteúdo do arquivo imediatamente antes dele (o que foi sobrescrito)."""
    r = git("log", "--format=%H", "-n", "80", "--", path, check=False)
    for commit in r.stdout.decode().split():
        atual = git("show", f"{commit}:{path}", check=False)
        if atual.returncode == 0 and atual.stdout == entregue:
            antes = git("show", f"{commit}^:{path}", check=False)
            return commit, (antes.stdout if antes.returncode == 0 else None)
    return None, None


def merge3(ours: bytes, base: bytes, theirs: bytes, rotulo: str) -> bytes | None:
    with tempfile.TemporaryDirectory() as tmp:
        fo, fb, ft = (Path(tmp) / n for n in ("ours", "base", "theirs"))
        fo.write_bytes(ours); fb.write_bytes(base); ft.write_bytes(theirs)
        r = subprocess.run(["git", "merge-file", "-p", str(fo), str(fb), str(ft)], capture_output=True)
        if r.returncode != 0:
            erros.append(f"{rotulo}: conflito ao combinar suas alterações com as minhas ({r.returncode} trecho(s)). Nada foi gravado.")
            return None
        return r.stdout


def linha_idx(linhas: list[str], alvo: str, inicio: int = 0) -> int:
    for i in range(inicio, len(linhas)):
        if linhas[i].strip() == alvo:
            return i
    return -1


def indent(linha: str) -> str:
    return linha[: len(linha) - len(linha.lstrip())]


# --------------------------------------------------------------------------- #
# 1) arquivos que eu entreguei inteiros: combinação em 3 vias
# --------------------------------------------------------------------------- #
def resolver_mesclado(path: str, base_key: str, v3_key: str, novo_key: str) -> bytes | None:
    head = ler(path)
    v3, novo, base = blob(v3_key), blob(novo_key), blob(base_key)
    if head == novo:
        return head
    commit, antes = versao_antes_do_meu_zip(path, v3)
    if head == v3 and commit:
        ours = antes if antes is not None else base
        if ours != base:
            relatorio.append(f"{path}: restauradas alterações feitas depois da minha base, que o zip havia sobrescrito")
        return merge3(ours, base, novo, path)
    if commit:  # editado depois do meu zip
        antes_ok = antes is None or antes == base
        if not antes_ok:
            avisos.append(f"{path}: foi editado depois do meu zip; mantive essas edições, mas o que o zip sobrescreveu antes não pôde ser recuperado automaticamente")
        return merge3(head if head is not None else v3, v3, novo, path)
    # meu zip nunca entrou neste arquivo
    return merge3(head if head is not None else base, base, novo, path)


# --------------------------------------------------------------------------- #
# 2) arquivos pequenos: restaura a versão do usuário e aplica só a minha mudança
# --------------------------------------------------------------------------- #
def versao_do_usuario(path: str, v3_key: str) -> bytes:
    head = ler(path) or b""
    commit, antes = versao_antes_do_meu_zip(path, blob(v3_key))
    if head == blob(v3_key) and commit and antes is not None:
        relatorio.append(f"{path}: restaurada a versão anterior ao zip e reaplicada só a minha alteração")
        return antes
    return head


def corrigir_template(conteudo: str) -> str | None:
    if "POSTGAME_OPENAI_MINI_MODEL" in conteudo:
        return conteudo
    linhas = conteudo.split("\n")
    for i, l in enumerate(linhas):
        if '"POSTGAME_OPENAI_MODEL"' in l:
            base_linha = l.rstrip()
            virgula = base_linha.endswith(",")
            linhas[i] = base_linha if virgula else base_linha + ","
            linhas.insert(i + 1, f'{indent(l)}"POSTGAME_OPENAI_MINI_MODEL": "gpt-4o-mini"' + ("," if virgula else ""))
            return "\n".join(linhas)
    erros.append(f"{P_TEMPLATE}: variável POSTGAME_OPENAI_MODEL não encontrada")
    return None


def corrigir_package(conteudo: str) -> str | None:
    try:
        pkg = json.loads(conteudo)
    except json.JSONDecodeError as e:
        erros.append(f"{P_PKG}: JSON inválido ({e})"); return None
    s = pkg.setdefault("scripts", {})
    chk = s.get("check", "")
    if "src/mailer.js" not in chk:
        alvo = "node --check src/postgame-fastlane.js"
        extra = "node --check src/mailer.js && node --check tests/test-mailer.mjs"
        s["check"] = chk.replace(alvo, f"{alvo} && {extra}", 1) if alvo in chk else (f"{chk} && {extra}" if chk else extra)
    ts = s.get("test:sports", "")
    if "tests/test-mailer.mjs" not in ts:
        alvo = "node tests/test-postgame-fastlane.mjs"
        s["test:sports"] = ts.replace(alvo, f"{alvo} && node tests/test-mailer.mjs", 1) if alvo in ts else (f"{ts} && node tests/test-mailer.mjs" if ts else "node tests/test-mailer.mjs")
    return json.dumps(pkg, ensure_ascii=False, indent=2) + "\n"


# --------------------------------------------------------------------------- #
# 3) workflow de deploy: restaura a versão atual e aplica 3 ajustes pontuais
# --------------------------------------------------------------------------- #
def corrigir_workflow() -> bytes | None:
    head = ler(P_WORKFLOW) or b""
    fix5 = blob("fix5_workflow")
    commit, antes = versao_antes_do_meu_zip(P_WORKFLOW, fix5)
    if head == fix5:
        if not (commit and antes):
            erros.append(f"{P_WORKFLOW}: é o arquivo desatualizado do zip e o histórico não tem a versão anterior")
            return None
        texto = antes.decode("utf-8")
        relatorio.append(f"{P_WORKFLOW}: restaurada a versão atual (anterior ao zip desatualizado)")
    else:
        texto = head.decode("utf-8")
    if "feedbackNotifier" not in texto:
        avisos.append(f"{P_WORKFLOW}: não encontrei as checagens de feedback; confira se esta é a versão mais recente")
    linhas = texto.split("\n")

    # (a) versão do fastlane lida do código publicado
    if "EXPECTED_POSTGAME" not in texto:
        i = next((k for k, l in enumerate(linhas) if l.strip().startswith('echo "Esperado pelo código local:')), -1)
        if i < 0:
            erros.append(f"{P_WORKFLOW}: linha 'Esperado pelo código local' não encontrada"); return None
        ind = indent(linhas[i])
        bloco = [
            "# Versão da política pós-jogo lida do próprio código publicado.",
            "EXPECTED_POSTGAME=\"$(node <<'NODE'",
            "const fs = require('fs');",
            "const s = fs.readFileSync('src/postgame-fastlane.js', 'utf8');",
            "const m = s.match(/POSTGAME_POLICY_VERSION\\s*=\\s*(\\d+)/);",
            "if (!m) process.exit(2);",
            "process.stdout.write(m[1]);",
            "NODE",
            ")\"",
            "",
        ]
        linhas[i] = linhas[i].rstrip()
        if linhas[i].endswith('"'):
            linhas[i] = linhas[i][:-1] + '; postgame=${EXPECTED_POSTGAME}"'
        linhas[i:i] = [ind + b if b else "" for b in bloco]

        j = linha_idx(linhas, "curl -fsS --max-time 10 'https://push.formuladogol.com.br/v1/postgame/status' >/tmp/fdg-postgame-status.json")
        if j < 0 or linhas[j + 1].strip() != "node <<'NODE'":
            erros.append(f"{P_WORKFLOW}: bloco do smoke test do fastlane não encontrado"); return None
        linhas[j + 1] = indent(linhas[j + 1]) + "EXPECTED_POSTGAME=\"$EXPECTED_POSTGAME\" SMTP_EXPECTED=\"${FDG_PUSH_SMTP_HOST:+1}\" node <<'NODE'"
        k = linha_idx(linhas, "if (s.ok !== true || s.engine !== 'cloudflare-postgame-fastlane' || Number(s.version) !== 2) {", j)
        if k < 0:
            erros.append(f"{P_WORKFLOW}: condição 'Number(s.version) !== 2' não encontrada"); return None
        ind = indent(linhas[k])
        linhas[k:k + 1] = [
            ind + "const expectedPostgame = Number(process.env.EXPECTED_POSTGAME);",
            ind + "if (s.ok !== true || s.engine !== 'cloudflare-postgame-fastlane' || Number(s.version) !== expectedPostgame) {",
        ]
        m = next((x for x in range(k, min(k + 12, len(linhas))) if linhas[x].strip().startswith("console.log(`Fastlane pós-jogo OK")), -1)
        if m < 0:
            erros.append(f"{P_WORKFLOW}: mensagem 'Fastlane pós-jogo OK' não encontrada"); return None
        ind = indent(linhas[m])
        linhas[m + 1:m + 1] = [
            ind + "if (process.env.SMTP_EXPECTED === '1' && !(s.mailer && s.mailer.transport === 'smtp' && s.mailer.configured === true)) {",
            ind + "  console.log(`::warning::E-mail do Worker ainda não aparece configurado (pode ser propagação): ${JSON.stringify(s.mailer || null)}`);",
            ind + "} else {",
            ind + "  console.log(`E-mail do Worker: ${s.mailer ? s.mailer.transport : 'indefinido'}`);",
            ind + "}",
        ]

    # (b) secrets de SMTP disponíveis para o job
    if not any(re.match(r"^\s*FDG_PUSH_SMTP_HOST:\s*\$\{\{", l) for l in linhas):
        e = next((k for k, l in enumerate(linhas) if re.match(r"^\s*FDG_PUSH_EMAIL_DESTINO:\s", l)), -1)
        if e < 0:
            erros.append(f"{P_WORKFLOW}: variável FDG_PUSH_EMAIL_DESTINO não encontrada no env"); return None
        ind = indent(linhas[e])
        linhas[e + 1:e + 1] = [ind + x for x in (
            "FDG_PUSH_EMAIL_DESTINO_SUGESTOES: ${{ secrets.EMAIL_DESTINO_SUGESTOES }}",
            "FDG_PUSH_SMTP_HOST: ${{ secrets.SMTP_HOST }}",
            "FDG_PUSH_SMTP_PORT: ${{ secrets.SMTP_PORT }}",
            "FDG_PUSH_SMTP_USER: ${{ secrets.SMTP_USER }}",
            "FDG_PUSH_SMTP_PASS: ${{ secrets.SMTP_PASS }}",
        )]

    # (c) grava os secrets de SMTP no Worker
    if not any("npx wrangler secret put SMTP_HOST" in l for l in linhas):
        a = linha_idx(linhas, "echo 'E-mail administrativo não configurado; preservando qualquer configuração já existente no Worker.'")
        if a >= 0 and a + 1 < len(linhas) and linhas[a + 1].strip() == "fi":
            pos, ind = a + 2, indent(linhas[a + 1])
        else:
            o = next((k for k, l in enumerate(linhas) if "npx wrangler secret put OPENAI_API_KEY" in l), -1)
            if o < 0:
                erros.append(f"{P_WORKFLOW}: passo de gravação de secrets não encontrado"); return None
            pos, ind = o + 1, indent(linhas[o])
        cfg = "--config wrangler.generated.jsonc"
        linhas[pos:pos] = [""] + [ind + x for x in (
            "# E-mail do Worker por SMTP: mesmos secrets do aviso de sugestões (Zoho).",
            'SMTP_DESTINO="${FDG_PUSH_EMAIL_DESTINO:-${FDG_PUSH_EMAIL_DESTINO_SUGESTOES:-}}"',
            'if [ -n "${FDG_PUSH_SMTP_HOST:-}" ] && [ -n "${FDG_PUSH_SMTP_USER:-}" ] && [ -n "${FDG_PUSH_SMTP_PASS:-}" ] && [ -n "$SMTP_DESTINO" ]; then',
            f"  printf '%s' \"$FDG_PUSH_SMTP_HOST\" | npx wrangler secret put SMTP_HOST {cfg}",
            f"  printf '%s' \"${{FDG_PUSH_SMTP_PORT:-465}}\" | npx wrangler secret put SMTP_PORT {cfg}",
            f"  printf '%s' \"$FDG_PUSH_SMTP_USER\" | npx wrangler secret put SMTP_USER {cfg}",
            f"  printf '%s' \"$FDG_PUSH_SMTP_PASS\" | npx wrangler secret put SMTP_PASS {cfg}",
            f"  printf '%s' \"$SMTP_DESTINO\" | npx wrangler secret put EMAIL_DESTINO {cfg}",
            "  echo 'Segredos SMTP do Worker atualizados.'",
            "else",
            "  echo 'AVISO: SMTP_* ou EMAIL_DESTINO_SUGESTOES ausentes; alertas por e-mail do Worker desativados.'",
            "fi",
        )]
    return "\n".join(linhas).encode("utf-8")


# --------------------------------------------------------------------------- #
# 4) alerta de readiness do monitor
# --------------------------------------------------------------------------- #
def corrigir_monitor() -> bytes | None:
    head = ler(P_MONITOR)
    if head is None:
        avisos.append(f"{P_MONITOR}: não encontrado; alerta de readiness não religado"); return None
    texto = head.decode("utf-8")
    if "sendMail(this.env" in texto:
        return head
    antigo, novo = blob("readiness_old").decode(), blob("readiness_new").decode()
    if antigo not in texto:
        avisos.append(f"{P_MONITOR}: o alerta de readiness mudou desde a minha base; não religado (continua como estava)")
        return None
    texto = texto.replace(antigo, novo, 1)
    imports = [m.end() for m in re.finditer(r"^import [^\n]+;\n", texto, re.M)]
    linha = "import { sendMail, mailConfig } from './mailer.js';\n"
    texto = texto[:imports[-1]] + linha + texto[imports[-1]:] if imports else linha + texto
    relatorio.append(f"{P_MONITOR}: alerta de 'jogo não está READY' passa a usar o SMTP")
    return texto.encode("utf-8")


# --------------------------------------------------------------------------- #
def validar() -> list[str]:
    falhas = []
    def rodar(cmd, cwd="."):
        r = subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)
        if r.returncode != 0:
            falhas.append(f"{' '.join(cmd)}\n{(r.stdout + r.stderr).strip()[-900:]}")
    for js in ("src/postgame-fastlane.js", "src/mailer.js", "src/sports-monitor.js", "tests/test-postgame-fastlane.mjs", "tests/test-mailer.mjs"):
        if Path(W, js).exists():
            rodar(["node", "--check", js], cwd=W)
    rodar(["node", "tests/test-postgame-fastlane.mjs"], cwd=W)
    rodar(["node", "tests/test-mailer.mjs"], cwd=W)
    rodar([sys.executable, "-m", "py_compile", P_IMPORTER])
    rodar([sys.executable, P_IMPORTER, "--self-test"])
    try:
        json.loads(Path(P_PKG).read_text(encoding="utf-8"))
    except Exception as e:
        falhas.append(f"{P_PKG}: {e}")
    try:
        import yaml  # type: ignore
        wf = yaml.safe_load(Path(P_WORKFLOW).read_text(encoding="utf-8"))
        for job in (wf.get("jobs") or {}).values():
            for passo in job.get("steps") or []:
                run = passo.get("run")
                if run and (passo.get("shell") in (None, "bash") or "bash" in str(passo.get("shell"))):
                    r = subprocess.run(["bash", "-n"], input=run, capture_output=True, text=True)
                    if r.returncode != 0:
                        falhas.append(f"workflow, passo '{passo.get('name', '?')}': {r.stderr.strip()}")
    except ImportError:
        avisos.append("PyYAML indisponível: sintaxe do workflow não verificada (instale com: pip install pyyaml)")
    except Exception as e:
        falhas.append(f"{P_WORKFLOW}: YAML inválido ({e})")
    return falhas


def main() -> int:
    if not (Path(W).is_dir() and Path(".github/workflows").is_dir()):
        print("Rode este script na RAIZ do repositório formuladogol."); return 2
    if git("rev-parse", "--is-shallow-repository", check=False).stdout.strip() == b"true":
        print("Histórico incompleto. Rode antes: git fetch --unshallow"); return 2
    alvos = [P_FAST, P_FAST_TEST, P_MAILER, P_MAILER_TEST, P_MIGR, P_TEMPLATE, P_PKG, P_MONITOR, P_IMPORTER, P_WORKFLOW]
    sujos = git("status", "--porcelain", "--", *alvos, check=False).stdout.decode().strip()
    if sujos:
        print("Há alterações não commitadas nestes arquivos. Faça commit ou descarte antes:\n" + sujos); return 2
    git("fetch", "-q", "origin", check=False)
    atras = git("rev-list", "--count", "HEAD..@{u}", check=False)
    if atras.returncode == 0 and atras.stdout.strip() not in (b"", b"0"):
        print("Seu Codespaces está atrás do GitHub. Rode antes: git pull"); return 2

    novos: dict[str, bytes] = {}
    for path, b, v3, nv in (
        (P_FAST, "base_fast", "v3_fast", "novo_fast"),
        (P_FAST_TEST, "base_fast_test", "v3_fast_test", "v3_fast_test"),
        (P_IMPORTER, "base_importer", "v3_importer", "v3_importer"),
    ):
        r = resolver_mesclado(path, b, v3, nv)
        if r is not None:
            novos[path] = r
    t = corrigir_template(versao_do_usuario(P_TEMPLATE, "v3_template").decode("utf-8"))
    if t is not None:
        novos[P_TEMPLATE] = t.encode("utf-8")
    p = corrigir_package(versao_do_usuario(P_PKG, "v3_pkg").decode("utf-8"))
    if p is not None:
        novos[P_PKG] = p.encode("utf-8")
    wf = corrigir_workflow()
    if wf is not None:
        novos[P_WORKFLOW] = wf
    mon = corrigir_monitor()
    if mon is not None:
        novos[P_MONITOR] = mon
    novos[P_MAILER] = blob("mailer")
    novos[P_MAILER_TEST] = blob("mailer_test")
    if ler(P_MIGR) is None:
        novos[P_MIGR] = blob("migration")

    if erros:
        print("NADA FOI ALTERADO. Problemas encontrados:")
        for e in erros: print(f"  ✗ {e}")
        return 1

    mudancas = {p: c for p, c in novos.items() if ler(p) != c}
    print("Arquivos que serão alterados:" if mudancas else "Nada a alterar: tudo já está aplicado.")
    for p in mudancas: print(f"  • {p}")
    for r in relatorio: print(f"  ↺ {r}")
    for a in avisos: print(f"  ⚠ {a}")
    if DRY or not mudancas:
        return 0

    backup = {p: ler(p) for p in mudancas}
    for p, c in mudancas.items():
        Path(p).parent.mkdir(parents=True, exist_ok=True)
        Path(p).write_bytes(c)
    falhas = validar()
    if falhas:
        for p, c in backup.items():
            if c is None: Path(p).unlink(missing_ok=True)
            else: Path(p).write_bytes(c)
        print("\nVALIDAÇÃO FALHOU — todas as alterações foram desfeitas:")
        for f in falhas: print(f"  ✗ {f}")
        return 1
    print("\nValidação: sintaxe, testes do fastlane, testes do e-mail, self-test do importador e workflow — OK")
    print("\nPróximo passo:")
    print("  git add -A")
    print('  git commit -m "E-mail do Worker via SMTP + reparo do deploy"')
    print("  git push")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
